export function groupBy(items, key) {
  const result = {};
  for (const item of items) {
    const value = item[key];
    if (!Object.prototype.hasOwnProperty.call(result, value)) {
      Object.defineProperty(result, value, {
        value: [],
        enumerable: true,
        writable: true,
        configurable: true,
      });
    }
    result[value].push(item);
  }
  return result;
}
